contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 initialSupply, address target) public {
        require(initialSupply > 0 && initialSupply <= 2**128);
        c = new C(initialSupply, "n", "s");
        c.freezeAccount(target, true); if (__ESBMC_reverted()) return;
        bool toFrozen;
        c.transfer(target, 1); bool __rev0 = __ESBMC_reverted(); if (__rev0) { toFrozen = true; } else { toFrozen = false; }
        bool frozen = c.frozenAccount(target); if (__ESBMC_reverted()) return;
        assert(toFrozen && frozen);
    }
    receive() external payable {}
}

